#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    int n;
    plik >> n;
    int maxVal = n, minVal = n;
    int maxAbs = (n < 0) ? -n : n;
    int minAbs = maxAbs;
    while (plik >> n) {
        int a = (n < 0) ? -n : n;
        if (a > maxAbs) { maxAbs = a; maxVal = n; }
        if (a < minAbs) { minAbs = a; minVal = n; }
    }
    cout << "Liczba o max |x|: " << maxVal << " (|" << maxVal << "| = " << maxAbs << ")" << endl;
    cout << "Liczba o min |x|: " << minVal << " (|" << minVal << "| = " << minAbs << ")" << endl;
    return 0;
}
```

